<script>
import { toRefs } from 'vue';
import controller from '../controllers/settings.js';
import { useMiniPage, rpxStyle } from '../runtime';
import MiniPicker from '../MiniPicker.vue';
import MiniSwitch from '../MiniSwitch.vue';
export default { name:'MiniSettings', components:{MiniPicker,MiniSwitch}, props:{query:Object}, setup(props) {
  const page = useMiniPage(controller, props.query || {}, ["skin","skinOptions","me","catName","dogName","avatarSaving","wechatAvatarIsImage","wechatAvatar","wechatNickname","avatarHelp","catIsImage","catAvatar","dogIsImage","dogAvatar","catStartRange","catStartValue","catStart","catStartInvalid","dogStartRange","dogStartValue","dogStart","dogStartInvalid","weekOptions","weeks","adjustmentDate","adjustmentMinDate","adjustmentMaxDate","adjustmentOwner","adjustmentKind","adjustmentSourceDate","adjustmentRows","sectionOwner","sections","sectionsExpanded","breakSectionCount","lunchOptions","lunchAfter","dinnerOptions","dinnerAfter","emojiSheet","emojis"], 'Settings');
  return { ...toRefs(page.data), fire:page.fire, rpxStyle };
}};
