    <template v-for="(item, index) in skinOptions" :key="item.value"><button :data-skin="item.value" @click="fire('chooseSkin', $event, {&quot;skin&quot;:(item.value)})" :class="&quot;skin-option preview-&quot; + (item.value) + &quot; &quot; + (skin===item.value?'on':'')" :aria-label="(item.name) + &quot;皮肤&quot;" type="button">
