    </button></template>
  </div>
</div>
<div class="card wechat-card"><div class="title">头像与昵称</div><span class="hint">当前身份是“<span :class="&quot;nick-&quot; + (me)">{{me==='cat'?catName:dogName}}</span>”。点击头像可从相册选择，昵称可以直接修改。</span><div class="wechat-profile"><button class="wechat-avatar" :data-owner="me" @click="fire('uploadAvatar', $event, {&quot;owner&quot;:(me)})" :disabled="avatarSaving" type="button"><img v-if="wechatAvatarIsImage" :src="wechatAvatar" alt="" style="object-fit:cover" /><span v-else>{{wechatAvatar}}</span></button><input :class="&quot;nickname nick-&quot; + (me)" type="text" :value="wechatNickname" placeholder="点击修改昵称" @blur="fire('useWechatNickname', $event, {})" /></div><div class="avatar-actions"><button class="wechat-choose" :data-owner="me" @click="fire('uploadAvatar', $event, {&quot;owner&quot;:(me)})" :disabled="avatarSaving" type="button">选择头像</button><button class="album-choose" :data-owner="me" @click="fire('uploadAvatar', $event, {&quot;owner&quot;:(me)})" :disabled="avatarSaving" type="button">从相册选择头像</button></div><span v-if="avatarHelp" class="hint avatar-help">{{avatarHelp}}</span></div>
