quot;key&quot;:(&quot;dinnerAfter&quot;)})"><div>第{{dinnerAfter}}节后{{dinnerAfter===breakSectionCount?'（末节，不显示）':''}} ›</div></MiniPicker></div></template><span v-else class="hint">至少添加两节课，才能设置休息位置。</span></div>
